    public EdtEditorFormPreviewTool(){super("form_preview","Inspect native projection state, refresh its current BM form model, or select by exact ID/name. mode=refresh, select, or capture=true performs a version-checked native rebuild with causal completion; no tab toggling, source mutation, editor save/discard or desktop input. Dirty editors are preserved and not refreshed. ready is projection freshness, editor_ready is tab availability; image_available and elapsed delay do not prove current rendering. expected_model_sha256 is an optional optimistic precondition from a previous observation. projection_freshness binds authoritative BM/model/source and installed native generation; visual correctness still requires inspecting the capture. list without capture does not render and may report unverified. Unsupported SDK/callback timeout/model/input change cannot return verified freshness. grid creates a separate annotated derivative.","""
        {"type":"object","additionalProperties":false,"properties":{"editor_id":{"type":"string"},"mode":{"type":"string","enum":["list","select","refresh"],"default":"list"},"element_name":{"type":"string"},"element_id":{"type":"integer"},"offset":{"type":"integer","minimum":0},"limit":{"type":"integer","minimum":1,"maximum":500},"expected_model_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"capture":{"type":"boolean"},"grid":{"type":"boolean","default":false},"grid_step":{"type":"integer","minimum":8,"maximum":500,"default":20},"auto_restore":{"type":"boolean","default":true}},"required":["editor_id"]}
        """);}
